<?php /** @package Meridian_News */ if ( post_password_required() ) { return; } ?><section id="comments" class="comments-area"><?php if ( have_comments() ) : ?><h2><?php printf( esc_html( _nx( '%1$s comment', '%1$s comments', get_comments_number(), 'comments title', 'meridian-news' ) ), number_format_i18n( get_comments_number() ) ); ?></h2><ol class="comment-list"><?php wp_list_comments( array( 'style' => 'ol', 'short_ping' => true, 'avatar_size' => 48 ) ); ?></ol><?php the_comments_pagination( array( 'prev_text' => __( 'Older comments', 'meridian-news' ), 'next_text' => __( 'Newer comments', 'meridian-news' ) ) ); endif; if ( ! comments_open() && get_comments_number() ) { ?><p class="no-comments"><?php esc_html_e( 'Comments are closed.', 'meridian-news' ); ?></p><?php } comment_form( array( 'title_reply' => __( 'Join the conversation', 'meridian-news' ), 'label_submit' => __( 'Post comment', 'meridian-news' ) ) ); ?></section>
